import numpy as np
from collections import Counter, defaultdict

def solve_extended_diagonal(grid):
    h, w = len(grid), len(grid[0])

    vals = []
    for r in range(h):
        for c in range(w):
            vals.append(grid[r][c])
    bg = Counter(vals).most_common(1)[0][0]

    result = [row[:] for row in grid]

    val_positions = defaultdict(list)
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                val_positions[v].append((r, c))

    for val, positions in val_positions.items():
        # Only process values that appear exactly twice
        if len(positions) == 2:
            sorted_pos = sorted(positions)

            prev_r, prev_c = sorted_pos[0]
            curr_r, curr_c = sorted_pos[1]

            dr = curr_r - prev_r
            dc = curr_c - prev_c

            if abs(dr) == 1 and abs(dc) == 1:
                if dr > 0 and dc < 0:
                    direction = (1, -1)  # down-left
                elif dr > 0 and dc > 0:
                    direction = (1, 1)   # down-right
                elif dr < 0 and dc < 0:
                    direction = (-1, -1)
                else:
                    direction = (-1, 1)

                br, bc = curr_r, curr_c
                nr, nc = br + direction[0], bc + direction[1]

                while True:
                    if not (0 <= nr < h and 0 <= nc < w):
                        break
                    if grid[nr][nc] != bg:
                        break
                    result[nr][nc] = val
                    nr += direction[0]
                    nc += direction[1]

    return result

